using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Create tools
var researchTools = new ResearchTools();
var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// Configure the agent
var agent = new ChatClientAgent(chatClient,
    "You are a research assistant. When given a topic, use the SearchWeb tool to find " +
    "relevant information (perform multiple searches with different queries for breadth), " +
    "then use SaveNote to record key findings. After gathering enough information, use " +
    "GetNotes to review all findings and provide a comprehensive summary to the user.");

// Get topic from user
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = tools,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

/// <summary>
/// Tools available to the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  [Searching: {query}]");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            // Extract text snippets from result blocks
            var snippets = ExtractSnippets(html);
            return snippets.Length > 0
                ? snippets
                : $"Search completed for '{query}' but no clear snippets were extracted. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a key finding.")]
    public string SaveNote(
        [Description("The title or category of the note")] string title,
        [Description("The content of the note")] string content)
    {
        _notes.Add($"[{title}]: {content}");
        Console.WriteLine($"  [Note saved: {title}]");
        return $"Note saved: '{title}'";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes);
    }

    private static string ExtractSnippets(string html)
    {
        // Simple extraction of result snippets from DuckDuckGo HTML
        var results = new List<string>();
        var snippetMarker = "result__snippet";
        var startIndex = 0;

        while (results.Count < 5)
        {
            var markerPos = html.IndexOf(snippetMarker, startIndex, StringComparison.Ordinal);
            if (markerPos < 0) break;

            var tagClose = html.IndexOf('>', markerPos);
            if (tagClose < 0) break;

            var endTag = html.IndexOf('<', tagClose + 1);
            if (endTag < 0) break;

            var snippet = html[(tagClose + 1)..endTag].Trim();
            if (snippet.Length > 20)
            {
                snippet = System.Net.WebUtility.HtmlDecode(snippet);
                results.Add(snippet);
            }

            startIndex = endTag;
        }

        return string.Join("\n\n", results);
    }
}

